function columnsInLevelOrder(root: TreeNode | null): number[][] {
  const items: [number, number, number, number][] = []; // col, row, order, val
  const stack: [TreeNode, number, number][] = root ? [[root, 0, 0]] : [];
  while (stack.length) {
    const [n, col, row] = stack.pop()!;
    items.push([col, row, items.length, n.val]);
    if (n.right) stack.push([n.right, col + 1, row + 1]);
    if (n.left) stack.push([n.left, col - 1, row + 1]);
  }
  items.sort((a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2]);
  const out: number[][] = [];
  for (let i = 0; i < items.length; i++) {
    if (i === 0 || items[i][0] !== items[i - 1][0]) out.push([]);
    out[out.length - 1].push(items[i][3]);
  }
  return out;
}

