class Solution:
    def columnsInLevelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        items = []
        stack = [(root, 0, 0)] if root else []
        while stack:
            n, col, row = stack.pop()
            items.append((col, row, len(items), n.val))
            if n.right:
                stack.append((n.right, col + 1, row + 1))
            if n.left:
                stack.append((n.left, col - 1, row + 1))
        items.sort()
        out = []
        for i, (col, _, _, v) in enumerate(items):
            if i == 0 or col != items[i - 1][0]:
                out.append([])
            out[-1].append(v)
        return out

