function columnsInLevelOrder(root: TreeNode | null): number[][] {
  if (!root) return [];
  const cols = new Map<number, number[]>();
  let lo = 0, hi = 0;
  const q: [TreeNode, number][] = [[root, 0]];
  for (let i = 0; i < q.length; i++) {
    const [n, c] = q[i];
    if (!cols.has(c)) cols.set(c, []);
    cols.get(c)!.push(n.val);
    lo = Math.min(lo, c); hi = Math.max(hi, c);
    if (n.left) q.push([n.left, c - 1]);
    if (n.right) q.push([n.right, c + 1]);
  }
  const out: number[][] = [];
  for (let c = lo; c <= hi; c++) out.push(cols.get(c)!);
  return out;
}

