            cols[c].append(n.val)
            lo, hi = min(lo, c), max(hi, c)
            if n.left:
                q.append((n.left, c - 1))
            if n.right:
                q.append((n.right, c + 1))
        return [cols[c] for c in range(lo, hi + 1)]

